(()=>{const root=document.getElementById("chapter-chap-2-model");const d=new Proxy(document,{get(t,k){if(k==='addEventListener'||k==='removeEventListener')return(type,...args)=>(type==='DOMContentLoaded'?t:root)[k](type,...args);if(k==='querySelector')return s=>root.querySelector(s);if(k==='querySelectorAll')return s=>root.querySelectorAll(s);if(k==='getElementById')return id=>root.id===String(id)?root:root.querySelector('[id="'+CSS.escape(String(id))+'"]');if(k==='body'||k==='documentElement')return root;const v=Reflect.get(t,k,t);return typeof v==='function'?v.bind(t):v;}});((document)=>{(function() {
  'use strict';

  // 状态管理
  const state = {
    activeTerm: null,
    arrayType: 'uca' // 'ula' or 'uca'
  };

  // DOM 元素缓存
  const elements = {
    formulaTerms: document.querySelectorAll('#chap-2-model--formula-h .term'),
    legendItems: document.querySelectorAll('.legend-item'),
    arrayDemos: {
      ula: document.getElementById('chap-2-model--demo-ula'),
      uca: document.getElementById('chap-2-model--demo-uca')
    },
    sourceButtons: document.querySelectorAll('[data-source]')
  };

  // 初始化
  function init() {
    bindFormulaEvents();
    bindLegendEvents();
    bindSourceEvents();
    // 默认高亮 UCA 相关项
    highlightTerm('ar');
  }

  // 绑定公式项交互
  function bindFormulaEvents() {
    elements.formulaTerms.forEach(term => {
      term.addEventListener('mouseenter', () => {
        const target = term.dataset.highlight;
        highlightTerm(target);
        updateArrayVisual(target);
      });

      term.addEventListener('mouseleave', () => {
        // 鼠标离开公式时，保持当前 Legend 的高亮状态，不立即清除
